from docx import Document
from docx.shared import RGBColor
import re, shutil, os, glob
files=glob.glob(os.path.expanduser('~/Desktop/*.docx'))
path=files[0]
backup=path+'.bak'
if not os.path.exists(backup): shutil.copy2(path, backup)
doc=Document(path)
vowels=set('aeiouAEIOU')
def color_paragraph(p):
    old=[]
    for run in list(p.runs):
        for part in re.split(r'([A-Za-z]+)', run.text):
            if part:
                old.append((part, run.bold, run.italic, run.underline, run.font.name, run.font.size, run.style, RGBColor(255,0,0) if part[0:1] in vowels else (RGBColor(0,0,255) if part[0:1].isalpha() else None)))
    for run in list(p.runs): p._element.remove(run._element)
    for text,bold,italic,underline,name,size,style,col in old:
        r=p.add_run(text)
        try: r.style=style
        except Exception: pass
        r.bold=bold; r.italic=italic; r.underline=underline
        if name: r.font.name=name
        if size: r.font.size=size
        if col: r.font.color.rgb=col
for p in doc.paragraphs: color_paragraph(p)
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for p in cell.paragraphs: color_paragraph(p)
doc.save(path)
print('DONE colored:', path)
PY
